from pathlib import Path


def add_permutations(w):
    w.page("Какая информация остаётся после обмена правками", "Что даёт правильная привязка к истории",
           "Если случайно перенести правку из другого проекта, её слова могут указать агенту на чужой репозиторий. Мы проверили результат ещё раз, разрешив обмениваться правками только внутри одного проекта.")
    w.p("Для каждого из 64 назначений переставили тексты между старыми карточками близкой длины. В первой серии донором мог быть любой проект, во второй — только тот же репозиторий. Все тексты сохранились, ни одна карточка не получила поле от самой себя. Использовали прежний лексический поиск и все 99 запросов Lite.")
    w.tbl(["Содержание поля", "Первая верна¹", "Первая верна, проект задан¹", "Есть в пятёрке¹"],
          [["Настоящие правки", "64", "65", "84"], ["Без поля правок", "61", "62", "83"],
           ["Обмен между любыми записями", "53–61 (57)", "54–62 (58)", "78–85 (83)"],
           ["Обмен внутри одного проекта", "51–60 (55)", "52–61 (56)", "78–84 (81)"]], [6.0,3.5,4.1,3.5],True)
    w.p("¹ У перестановок указаны минимум, максимум и медиана из 64 контрольных назначений. Второй числовой столбец получен фильтрацией прежнего полного рейтинга по репозиторию запроса. Частоты слов рассчитаны по одному и тому же корпусу. Знаменатель каждого значения — 99 запросов.", "Caption")
    picture = Path(__file__).resolve().parent / "write_factor/perm_robustness/permutation_scores.png"
    w.doc.add_picture(str(picture), width=w.Cm(16.8))
    w.p("Распределение 64 назначений каждого типа. Пунктир отмечает 61 правильный выбор без поля, сплошная линия — 64 выбора с настоящими правками.", "Caption")
    w.p("В полном пуле первое место принадлежало нужному проекту 94 раза с исходными правками, 94 раза без них и 94 раза при каждой из 64 внутрипроектных перестановок. При одинаковом числе верных проектов ни одна перестановка не достигла исходных 64 правильных первых историй. При оценке первой пятёрки уровень исходных правок достигнут 10 раз при глобальном и 3 раза при внутрипроектном обмене.")
    w.p("Практической альтернативой служит короткая карточка без правок. Она уступила правильно заполненной всего три первых выбора. Среди 13 задач вне Lite, для которых в прежней библиотеке вообще имелась метка, лексический поиск дал 11 верных первых записей. Это значение достигли 29 из 64 глобальных контролей. Итог зависит от корпуса и от того, оценивается одна позиция или пять.")
    w.p("Такие перестановки исследуют роль связи между конкретным исправлением и прежней задачей. Они повторно используют те же вопросы и исходные тексты. Разброс по донорам не измеряет неопределённость при переносе на новые репозитории.", "Caption")

